async ({ workspace: { read, search } }) => {
  const [cs, rk, pre, gitr] = await Promise.all([
    read("src/functions/command-source.ts", { format: "raw" }),
    search("ResultRendererKey", { path: "src", limit: 20, contextLines: 0 }),
    read("src/functions/global-contract-preamble.d.ts", { format: "raw" }),
    search("git\\.tag|git\\.push", { path: "src", regex: true, limit: 30, contextLines: 0 }),
  ]);
  const sl = (r: any) => r.matches?.map((m: any) => `${m.file}:${m.line}: ${m.text?.slice(0, 160)}`) ?? r;
  return { cs: cs.content, rk: sl(rk), pre: pre.content.slice(0, 12000), preLen: pre.content.length, gitr: sl(gitr) };
}
